<script setup>import {reactive,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {api,useSession,toast} from '../core';import Icon from '../components/Icon.vue';const mode=ref('login'),busy=ref(false),error=ref(''),route=useRoute(),router=useRouter(),session=useSession(),form=reactive({account:'',password:'',confirmPassword:''});async function submit(){busy.value=true;error.value='';try{if(mode.value==='register'){await api('/auth/register','POST',form);toast('注册成功，请登录');mode.value='login'}else{const r=await api('/auth/login','POST',{account:form.account,password:form.password});session.token=r.accessToken;session.user=r.user;const next=typeof route.query.next==='string'&&route.query.next.startsWith('/')&&!route.query.next.startsWith('//')?route.query.next:'/account';router.push(next);toast('欢迎回来，'+r.user.nickname)}}catch(e){error.value=e.message}finally{busy.value=false;form.password='';form.confirmPassword=''}};</script><template><section class="shell auth-layout"><div class="auth-art"><img src="/assets/hero.webp" alt="彼此陪伴的猫狗"><div><p class="eyebrow">WELCOME TO PET HAVEN</p><h2>美好的陪伴，<br>从认识彼此开始。</h2></div></div><div class="auth-form"><span class="eyebrow">一起开启新的故事</span><h1>{{mode==='login'?'欢迎回来。':'很高兴认识你。'}}</h1><p class="muted">{{mode==='login'?'登录寻爪，继续你与它的故事。':'创建账号，遇见值得一生陪伴的伙伴。'}}</p><div class="tabs"><button :class="{active:mode==='login'}" @click="mode='login';error=''">登录</button><button :class="{active:mode==='register'}" @click="mode='register';error=''">注册</button></div><form class="form-stack" @submit.prevent="submit"><label>账号<input v-model="form.account" autocomplete="username" required maxlength="16" placeholder="4–16位字母、数字或下划线"></label><label>密码<input v-model="form.password" type="password" :autocomplete="mode==='login'?'current-password':'new-password'" required placeholder="请输入密码"></label><label v-if="mode==='register'">确认密码<input v-model="form.confirmPassword" type="password" autocomplete="new-password" required placeholder="再次输入密码"></label><p v-if="mode==='register'" class="hint">密码8–32个字符，包含字母和数字。普通注册仅创建用户账号。</p><p v-if="error" class="error" role="alert">{{error}}</p><button class="btn wide" :disabled="busy">{{busy?'正在处理…':mode==='login'?'登录寻爪':'创建账号'}}<Icon name="arrow" :size="18"/></button></form><p class="hint">为保护账号，会话30分钟到期，刷新页面需重新登录。</p></div></section></template>
